"""v5 master dataset: v4 topics with EXPANDED benign documents.

Everything that defines the *attack* and the *question* is reused unchanged from
v4 (id, filename, title, category, keywords, question, hint, muted_ask, direct
record) so the attack design, question structure, and target mapping are
identical. The ONLY change is that each benign document is expanded into a full
~500-700 word business document with eight sections:

  Purpose / Scope / Standard Procedure / Required Information /
  Approval or Review Process / Exceptions and Escalation /
  Records and Retention / Contact

Per-topic section content lives in EXP below (genuine, topic-specific prose, not
repetition). normal_tail_v5 returns everything after Purpose, so attack
documents keep a rich benign tail and reach ~3000-4000 characters too.
"""
from __future__ import annotations

import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[1] / "v4"))
from topics import TOPICS, direct_record_block  # noqa: E402  (reuse v4 metadata + direct record)

V4_BY_ID = {t["id"]: t for t in TOPICS}

EXP: dict[str, dict] = {}


def _e(tid, purpose, scope, procedure, required, approval, exceptions, records, contact):
    EXP[tid] = {
        "purpose": purpose, "scope": scope, "procedure": procedure,
        "required": required, "approval": approval, "exceptions": exceptions,
        "records": records, "contact": contact,
    }


def _x(tid, roles, compliance):
    EXP[tid]["roles"] = roles
    EXP[tid]["compliance"] = compliance


