# === END X ENTRIES ===

SECTION_ORDER = [
    ("Purpose", "purpose"),
    ("Scope", "scope"),
    ("Roles and Responsibilities", "roles"),
    ("Standard Procedure", "procedure"),
    ("Required Information", "required"),
    ("Approval or Review Process", "approval"),
    ("Exceptions and Escalation", "exceptions"),
    ("Records and Retention", "records"),
    ("Compliance, Training and Review", "compliance"),
    ("Contact", "contact"),
]


def build_normal_text_v5(topic: dict) -> str:
    e = EXP[topic["id"]]
    lines = [topic["title"], ""]
    for heading, key in SECTION_ORDER:
        lines.append(heading)
        lines.append(e[key])
        lines.append("")
    return "\n".join(lines).rstrip() + "\n"


def normal_tail_v5(topic: dict) -> str:
    """Benign tail = everything after Purpose (Scope ... Contact)."""
    e = EXP[topic["id"]]
    lines = []
    for heading, key in SECTION_ORDER[1:]:
        lines.append(heading)
        lines.append(e[key])
        lines.append("")
    return "\n".join(lines).rstrip() + "\n"


if __name__ == "__main__":
    missing = {t["id"] for t in TOPICS} - set(EXP)
    extra = set(EXP) - {t["id"] for t in TOPICS}
    assert not missing, f"missing EXP for ids: {sorted(missing)}"
    assert not extra, f"extra EXP ids: {sorted(extra)}"
    chars = [len(build_normal_text_v5(t)) for t in TOPICS]
    words = [len(build_normal_text_v5(t).split()) for t in TOPICS]
    print(f"topics={len(TOPICS)} EXP={len(EXP)}")
    print(f"chars min/max/avg = {min(chars)}/{max(chars)}/{sum(chars)//len(chars)}")
    print(f"words min/max/avg = {min(words)}/{max(words)}/{sum(words)//len(words)}")
    below = [t['id'] for t, c in zip(TOPICS, chars) if c < 3000]
    if below:
        print(f"WARNING <3000 chars: {below}")
